def seed_role_groups(apps, schema_editor):
    Group = apps.get_model('auth', 'Group')
    Permission = apps.get_model('auth', 'Permission')
    ContentType = apps.get_model('contenttypes', 'ContentType')
    RoleGroup = apps.get_model('accounts', 'RoleGroup')
    db = schema_editor.connection.alias

    # On a fresh database Django creates permission rows only after every
    # migration has run (post_migrate), so the ones granted here are made now;
    # create_permissions later finds them and leaves them alone.
    user_type, _ = ContentType.objects.using(db).get_or_create(app_label='accounts', model='user')
    hub_type, _ = ContentType.objects.using(db).get_or_create(app_label='accounts', model='hubpermission')
    permissions = {
        'view_team': Permission.objects.using(db).get_or_create(
            content_type=user_type, codename='view_team', defaults={'name': 'Can view the team directory'},
        )[0],
    }
    for codename, name in HUB_PERMISSIONS:
        permissions[codename] = Permission.objects.using(db).get_or_create(
            content_type=hub_type, codename=codename, defaults={'name': name},
        )[0]

    for role, name, codenames in ROLE_GROUPS:
        if RoleGroup.objects.using(db).filter(role=role).exists():
            continue
        if Group.objects.using(db).filter(name=name).exists():
            raise RuntimeError(
                f'A group named "{name}" already exists. Rename or remove it before migrating: '
                'the role groups are created here, never adopted.'
            )
        group = Group.objects.using(db).create(name=name)
        RoleGroup.objects.using(db).create(role=role, group=group)
        group.permissions.add(*(permissions[codename] for codename in codenames))


def unseed_role_groups(apps, schema_editor):
    Group = apps.get_model('auth', 'Group')
    Permission = apps.get_model('auth', 'Permission')
    ContentType = apps.get_model('contenttypes', 'ContentType')
    RoleGroup = apps.get_model('accounts', 'RoleGroup')
    db = schema_editor.connection.alias
    for link in RoleGroup.objects.using(db).select_related('group'):
        group_id = link.group_id
        link.delete()
        Group.objects.using(db).filter(pk=group_id).delete()
    hub_type = ContentType.objects.using(db).filter(app_label='accounts', model='hubpermission')
    Permission.objects.using(db).filter(content_type__in=hub_type).delete()
    hub_type.delete()


